export function setupBlackholeControls(section,uniform,{preset,dirty}){
 Object.assign(uniform,{diskTilt:{value:0},innerRadius:{value:3},spectrum:{value:0},hotspot:{value:0},disruption:{value:0},eventAge:{value:0},splitView:{value:0},beaming:{value:1}});
 const panel=document.createElement('div');panel.className='blackhole-advanced';panel.innerHTML='<div class="advanced-heading"><span class="eyebrow">BLACK HOLE / OPTICAL EXPERIMENTS</span><strong>Change what the light encounters.</strong></div><label>Emission spectrum<select id="bh-spectrum"><option value="0">Thermal / amber white</option><option value="1">Infrared / warm dust</option><option value="2">High energy / violet blue</option></select></label><label>Disk tilt / °<input id="bh-tilt" type="range" min="-40" max="40" value="0"></label><label>Inner emission radius / Rs<input id="bh-inner" type="range" min="1.4" max="6" step=".05" value="3"></label><div class="advanced-actions"><button id="bh-hotspot" aria-pressed="false">Orbiting hot spot</button><button id="bh-beaming" aria-pressed="true">Doppler brightening</button><button id="bh-compare" aria-pressed="false">Compare lensing</button><button id="bh-disrupt">Disrupt a star ✦</button><button id="bh-photon-pass">Photon pass camera ↗</button><button id="bh-export-4k">Export 4K image ↧</button></div><p id="bh-event-status" role="status">Optical emission experiments · static, nonrotating space-time · synthetic disk and stellar disruption.</p>';
 section.querySelector('.bh-console').after(panel);const $=s=>panel.querySelector(s);let eventRunning=false;
 $('#bh-spectrum').onchange=e=>{uniform.spectrum.value=+e.target.value;dirty()};$('#bh-tilt').oninput=e=>{uniform.diskTilt.value=+e.target.value*Math.PI/180;dirty()};$('#bh-inner').oninput=e=>{uniform.innerRadius.value=+e.target.value;dirty()};
 for(const [id,key] of [['#bh-hotspot','hotspot'],['#bh-beaming','beaming'],['#bh-compare','splitView']])$(id).onclick=e=>{uniform[key].value=1-uniform[key].value;e.currentTarget.setAttribute('aria-pressed',!!uniform[key].value);section.classList.toggle('blackhole-split',!!uniform.splitView.value);dirty()};
 $('#bh-disrupt').onclick=()=>{uniform.disruption.value=1;uniform.eventAge.value=0;eventRunning=true;$('#bh-event-status').textContent='STELLAR DISRUPTION / synthetic star stretches into an accretion stream';dirty()};$('#bh-photon-pass').onclick=()=>preset('photon');$('#bh-export-4k').onclick=()=>section.querySelector('#bh-capture').click();
 const compare=document.createElement('div');compare.className='bh-comparison-labels';compare.innerHTML='<span>STRAIGHT LIGHT PATHS</span><span>CURVED LIGHT PATHS</span>';section.querySelector('.horizon-hero').append(compare);
 return {frame(dt,moving){if(eventRunning&&moving){uniform.eventAge.value=Math.min(1,uniform.eventAge.value+dt*.085);if(uniform.eventAge.value===1){eventRunning=false;uniform.disruption.value=0;$('#bh-event-status').textContent='EVENT COMPLETE / replay disruption or adjust the disk';}dirty()}}};
}
